CREATE TABLE "public"."purchase_tracking" (
  "purchase_check_id"              bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "job_id"                         bigint                   NOT NULL,
  "doors_ordered_at"               timestamp with time zone,
  "doors_received_at"              timestamp with time zone,
  "glass_ordered_at"               timestamp with time zone,
  "glass_received_at"              timestamp with time zone,
  "handles_ordered_at"             timestamp with time zone,
  "handles_received_at"            timestamp with time zone,
  "acc_ordered_at"                 timestamp with time zone,
  "acc_received_at"                timestamp with time zone,
  "purchasing_comments"            text,
  "updated_at"                     timestamp with time zone DEFAULT now(),
  "doors_received_incomplete_at"   timestamp with time zone,
  "glass_received_incomplete_at"   timestamp with time zone,
  "handles_received_incomplete_at" timestamp with time zone,
  "acc_received_incomplete_at"     timestamp with time zone,
  CONSTRAINT "purchase_tracking_job_id_fkey" FOREIGN KEY (job_id) REFERENCES public.jobs(id) ON DELETE CASCADE,
  CONSTRAINT "purchase_tracking_job_id_key" UNIQUE (job_id),
  CONSTRAINT "purchase_tracking_pkey" PRIMARY KEY (purchase_check_id)
);

ALTER TABLE "public"."purchase_tracking"
  ENABLE ROW LEVEL SECURITY;

CREATE TRIGGER set_updated_at
  BEFORE UPDATE ON public.purchase_tracking
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_updated_at();

CREATE POLICY "Enable delete for admin only" ON "public"."purchase_tracking"
  FOR DELETE
  TO PUBLIC
  USING ((public.clerk_user_role() = 'admin'::text));

CREATE POLICY "Enable insert for purchasing editors" ON "public"."purchase_tracking"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'scheduler'::text])));

CREATE POLICY "Enable read access for authenticated users" ON "public"."purchase_tracking"
  FOR SELECT
  TO PUBLIC
  USING ((auth.role() = 'authenticated'::text));

CREATE POLICY "Enable update for purchasing editors" ON "public"."purchase_tracking"
  FOR UPDATE
  TO PUBLIC
  USING ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'scheduler'::text])));

REVOKE ALL ON SEQUENCE "public"."purchase_tracking_purchase_check_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."purchase_tracking_purchase_check_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."purchase_tracking_purchase_check_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."purchase_tracking_purchase_check_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."purchase_tracking_purchase_check_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."purchase_tracking_purchase_check_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."purchase_tracking_purchase_check_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."purchase_tracking_purchase_check_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."purchase_tracking" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."purchase_tracking" TO "service_role";

REVOKE ALL ON TABLE "public"."purchase_tracking" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."purchase_tracking" TO "postgres";
